import{_ as a,o as s,c as e,a2 as n}from"./chunks/framework.BS0bAV7E.js";const m=JSON.parse('{"title":"文件系统与存储","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/filesystems.md","filePath":"zh/manual/filesystems.md"}'),o={name:"zh/manual/filesystems.md"};function i(l,t,d,c,p,r){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="文件系统与存储" tabindex="-1">文件系统与存储 <a class="header-anchor" href="#文件系统与存储" aria-label="Permalink to &quot;文件系统与存储&quot;">​</a></h1><h2 id="vfs" tabindex="-1">VFS <a class="header-anchor" href="#vfs" aria-label="Permalink to &quot;VFS&quot;">​</a></h2><p>所有文件访问都通过一个 VFS（<code>fs/fs_vfs.c</code>）进行：这是一个统一的 open/read/write/seek/close/stat/mkdir/rmdir/readdir/lookup API，支持 可插拔的文件系统类型。路径遍历全局节点树并透明地跨越 挂载点。每个文件系统的大小写敏感性、强制权限位和 64 位寻址偏移量都是真实的 VFS 行为。</p><h2 id="文件系统类型" tabindex="-1">文件系统类型 <a class="header-anchor" href="#文件系统类型" aria-label="Permalink to &quot;文件系统类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>读取</th><th>写入</th><th>存储位置</th></tr></thead><tbody><tr><td>ramfs</td><td>是</td><td>是</td><td>内存（易失）- 默认根文件系统</td></tr><tr><td>FAT32</td><td>是</td><td>是</td><td>任何块设备；支持长文件名</td></tr><tr><td>exFAT</td><td>是</td><td>是</td><td>任何块设备</td></tr><tr><td>ext4</td><td>是</td><td>是</td><td>任何块设备（基于扩展）</td></tr><tr><td>/etc 卷</td><td>是</td><td>是</td><td>挂载在 /etc 的小型 FAT32 镜像</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; dskstat                     (list block devices)</span></span>
<span class="line"><span>oc&gt; mkfs.fat32 ata0 confirm     (format - the confirm arg is required)</span></span>
<span class="line"><span>oc&gt; mkfs.exfat usda confirm</span></span>
<span class="line"><span>oc&gt; mkfs.ext4 ata0 confirm</span></span>
<span class="line"><span>oc&gt; fatmount ata0 /mnt          (mount FAT32)</span></span>
<span class="line"><span>oc&gt; mount                       (list mounts; umount unmounts)</span></span></code></pre></div><p>格式化是破坏性操作 - 每个 <code>mkfs.*</code> 都需要字面意义的 <code>confirm</code> 参数，以防意外的 Enter 键擦除磁盘。</p><h2 id="etc-卷" tabindex="-1">/etc 卷 <a class="header-anchor" href="#etc-卷" aria-label="Permalink to &quot;/etc 卷&quot;">​</a></h2><p>一个 32 MiB 的 FAT32 镜像，保存系统的持久状态：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>opencube.conf     (key=value system configuration - see \`config\`)</span></span>
<span class="line"><span>ssh host keys     (sshd identity - see [network](network.md))</span></span>
<span class="line"><span>kernel.log        (rotated kernel log - see [../internals/klog.md])</span></span>
<span class="line"><span>crash dumps       (see [recovery](recovery.md))</span></span></code></pre></div><p>配置的读写通过 <code>config</code> 命令和 L1 <code>l1_ext_config_*</code> 接口族进行；/etc 卷在启动时 如果存在会自动挂载。</p><h2 id="块设备" tabindex="-1">块设备 <a class="header-anchor" href="#块设备" aria-label="Permalink to &quot;块设备&quot;">​</a></h2><p>块层为实例命名（<code>ata0</code>、<code>usda</code>、<code>nvme0</code>、<code>vdisk0</code> 用于 virtio，<code>sd0</code> 用于 SD），并在其上提供 分区扫描：</p><ul><li><strong>ATA/ATAPI</strong> PIO 和总线主控 DMA（PRDT 对齐由 堆的 32 字节头块保证）</li><li><strong>AHCI</strong> - SATA 控制器</li><li><strong>NVMe</strong> - PCIe SSD</li><li><strong>virtio-blk</strong> - QEMU 下的快速路径（<code>-device virtio-blk-pci</code>）</li><li><strong>USB MSC</strong> - 通过任何 USB 栈的 大容量存储设备</li><li><strong>SD/SDHCI</strong> 和 <strong>SCSI</strong>（LSI 53C8xx 系列）控制器</li></ul><h2 id="分区表" tabindex="-1">分区表 <a class="header-anchor" href="#分区表" aria-label="Permalink to &quot;分区表&quot;">​</a></h2><p>扫描 GPT 和 MBR（msdos）分区表；分区设备 与整盘设备一起出现。支持 <code>fdisk</code> 风格的检查 和每个分区的挂载 - 请参阅磁盘域的 <a href="./commands/">命令参考</a>。</p><h2 id="文件命令" tabindex="-1">文件命令 <a class="header-anchor" href="#文件命令" aria-label="Permalink to &quot;文件命令&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; ls /mnt</span></span>
<span class="line"><span>oc&gt; cat /mnt/hello.txt</span></span>
<span class="line"><span>oc&gt; write /mnt/hello.txt &quot;new content&quot;</span></span>
<span class="line"><span>oc&gt; cp /mnt/a.txt /mnt/b.txt</span></span>
<span class="line"><span>oc&gt; mv /mnt/a.txt /mnt/c.txt</span></span>
<span class="line"><span>oc&gt; rm /mnt/c.txt</span></span>
<span class="line"><span>oc&gt; mkdir /mnt/dir</span></span>
<span class="line"><span>oc&gt; touch /mnt/empty.txt</span></span>
<span class="line"><span>oc&gt; editor /mnt/notes.txt        (full-screen editor)</span></span>
<span class="line"><span>oc&gt; fsck ata0                     (filesystem check)</span></span>
<span class="line"><span>oc&gt; fstest                        (VFS + per-fs self-test suite)</span></span></code></pre></div><h2 id="值得了解的限制" tabindex="-1">值得了解的限制 <a class="header-anchor" href="#值得了解的限制" aria-label="Permalink to &quot;值得了解的限制&quot;">​</a></h2><ul><li>长路径和文件名：FAT32 LFN 完全支持，包括 生成带冲突扫描的别名，以及在读取时进行校验和/序列 验证。</li><li>FAT32 维护双 FAT 镜像和 FSINFO 空闲簇提示； exFAT 跟踪活动的 FAT。</li><li>ramfs 稀疏空洞读回为零。</li><li>拒绝 <code>umount /</code>；挂载阴影不会复制子项。</li></ul>`,20)])])}const u=a(o,[["render",i]]);export{m as __pageData,u as default};
